INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (29, 2000, 'Art and Culture', 'Art and Craft', 'The Raga which is sung early in the morning is:', '{"a":"Todi","b":"Darbari","c":"Bhopali","d":"Bhimpalasi"}', 'a', '');
