INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (56, 2006, 'Art and Culture', 'Indian Culture and Heritage', 'Match List I with List II and select the correct answer using the code given below the lists: List. I (Finding / Invention/ Calculation) List. II (Ancient Indian Scholar) A. Time Taken by the Earth to orbit the Sun 1. Aryabhatta B. Calculation of the value of (.pi.) 2. Bhaskaracharya C. Invention of the digit zero 3. Budhayana D. The game of snakes and ladders 4. Gyandev A B C D', '{"a":"2 4 1 3","b":"2 3 1 4","c":"1 3 2 4","d":"1 4 2 3"}', 'b', '');
