INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (302, 1998, 'Medieval Indian History', 'Kingdoms and Rulers', 'The Sultan of Delhi who is reputed to have built the biggest network of canals in India was', '{"a":"Iltutmish","b":"Ghiyasuddin Tughlaq","c":"Feroz Shah Tughlaq","d":"Sikandar Lodi"}', 'c', '');
INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (303, 1997, 'Medieval Indian History', 'Kingdoms and Rulers', 'After consolidating his power, Balban assumed the grand title of:', '{"a":"Tute-i-Hind","b":"Kaisr-i-Hind","c":"Zil-i-Ilahi","d":"Din-i-Ilahi"}', 'c', '');
