INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (310, 2024, 'Medieval Indian History', 'Advent of Europeans', 'Who of the following rulers of medieval India gave permission to the Portuguese to build a fort at Bhatkal?', '{"a":"Krishnadevaraya","b":"Narasimha Saluva","c":"Muhammad Shah III","d":"Yusuf Adil Shah"}', 'a', '');
INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (311, 2023, 'Medieval Indian History', 'Advent of Europeans', 'Who among the following rulers of medieval Gujarat surrendered Diu to Portuguese?', '{"a":"Ahmad Shah","b":"Mahmud Begarha","c":"Bahadur Shah","d":"Muhammad Shah"}', 'c', '');
INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (312, 2022, 'Medieval Indian History', 'Advent of Europeans', 'With reference to Indian history, consider the following statements: 1. The Dutch established their factories/ warehouses on the east coast on lands granted to them by Gajapati rulers. 2. Alfonso de Albuquerque captured Goa from the Bijapur Sultanate. 3. The English East India Company established a factory at Madras on a plot of land leased from a representative of the Vijayanagara empire. Which of the statements given above are correct?', '{"a":"1 and 2 only","b":"2 and 3 only","c":"1 and 3 only","d":"1, 2 and 3"}', 'b', '');
INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (313, 2021, 'Medieval Indian History', 'Advent of Europeans', 'In the first quarter of seventeenth century, in which of the following was/were the factory/factories of the English East India Company located? 1) Broach 2) Chicacole 3) Trichinopoly Select the correct answer using the code given below.', '{"a":"1 only","b":"1 and 2","c":"3 only","d":"2 and 3"}', 'a', '');
INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (314, 2021, 'Medieval Indian History', 'Advent of Europeans', 'Consider the following statements: 1) Francis Xavier was one of the founding members of the Jesuit Order 2) Francis Xavier died in Goa and a church is dedicated to him there 3) The Feast of St. Francis Xavier is celebrated in Goa each year Which of the statements given above are correct?', '{"a":"1 and 2 only","b":"2 and 3 only","c":"1 and 3 only","d":"1, 2 and 3"}', 'c', '');
INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (315, 2010, 'Medieval Indian History', 'Advent of Europeans', 'With reference to the Pondicherry (now Puducherry), consider the following statements: 1. The first European power to occupy Pondicherry were the Portuguese. 2. The second European power to occupy Pondicherry were the French. 3. The English never occupied Pondicherry. Which of the statements given above is/are correct?', '{"a":"1 only","b":"2 and 3 only","c":"3 only","d":"1, 2 and 3"}', 'a', '');
INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (316, 2009, 'Medieval Indian History', 'Advent of Europeans', 'With whose permission did the English set up their first factory in Surat?', '{"a":"Akbar","b":"Jahangir","c":"Shahjahan","d":"Aurangzeb"}', 'b', '');
INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (317, 2008, 'Medieval Indian History', 'Advent of Europeans', 'During the time of which Mughal Emperor did the Engilsh East India Company establish its first factory in India?', '{"a":"Akbar","b":"Shahjahan","c":"Jahangir","d":"Aurangzeb"}', 'c', '');
INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (318, 2006, 'Medieval Indian History', 'Advent of Europeans', 'In the year 1613, where was the English East India Company given permission to set up a factory (trading post)?', '{"a":"Bangalore","b":"Madras","c":"Masulipatnam","d":"Surat"}', 'd', '');
INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (319, 2005, 'Medieval Indian History', 'Advent of Europeans', 'Which one of the following is the correct statement?', '{"a":"The modern Kochi was a Dutch colony till India’s independence.","b":"The Dutch defeated the Portuguese and built Fort Williams in the modern Kochi.","c":"The modern Kochi was first a Dutch colony before the Portuguese took over from them.","d":"Modern Kochi never became a part of the British colony."}', 'd', '');
INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (320, 2003, 'Medieval Indian History', 'Advent of Europeans', 'In India, among the following locations, the Dutch established their earliest factory at:', '{"a":"Surat","b":"Pulicat","c":"Cochin","d":"Cassimbazar"}', 'b', '');
INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (321, 2003, 'Medieval Indian History', 'Advent of Europeans', 'With reference to the entry of European powers into India, which one of the following statements is not correct?', '{"a":"The Portuguese captured Goa in 1499","b":"The English opened their first factory in South India at Masulipatam","c":"In Eastern India, the English Company opened its first factory in Orissa in 1633","d":"Under the leadership of supleix, the French occupied Madras in 1746"}', 'a', '');
INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (322, 1999, 'Medieval Indian History', 'Advent of Europeans', 'Which one of the following pairs is not correctly matched?', '{"a":"Jahangir: William Hawkins","b":"Akbar: Sir Thomas Roe","c":"Shahjahan: Travernier","d":"Aurangzeb: Manucci"}', 'b', '');
INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (323, 2022, 'Medieval Indian History', 'Art Architecture and Literature', '“Yogavasistha” was translated into Persian by Nizamuddin Panipati during the reign of:', '{"a":"Akbar","b":"Humayun","c":"Shahjahan","d":"Aurangzeb"}', 'a', '');
