INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (326, 2019, 'Medieval Indian History', 'Art Architecture and Literature', 'Who among the following Mughal Emperors shifted emphasis from illustrated manuscripts to album and individual portrait?', '{"a":"Humayun","b":"Akbar","c":"Jahangir","d":"Shah Jahan"}', 'c', '');
INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (327, 2019, 'Medieval Indian History', 'Art Architecture and Literature', 'Building Kalyaana Mandapas was a notable feature in the temple construction in the kingdom of:', '{"a":"Chalukya","b":"Chandela","c":"Rashtrakuta","d":"Vijayanagara"}', 'd', '');
INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (328, 2018, 'Medieval Indian History', 'Art Architecture and Literature', 'With reference to the cultural history of India, consider the following statements: 1. White marble was used in making Buland Darwaza and Khankah at Fatehpur Sikri 2. Red Sandstone and marble were used in making Bara Imambara and Rumi Darwaza in Lucknow Which of the following statements given above is/are correct?', '{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"}', 'd', '');
INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (329, 2014, 'Medieval Indian History', 'Art Architecture and Literature', 'Ibadat Khana at Fatehpur Sikri was:', '{"a":"The mosque for the use of Royal Family","b":"Akbar’s private prayer chamber","c":"The hall in which Akbar held discussions with scholars of various religions","d":"The room in which the nobles belonging in different religions gathered to discuss religious affairs"}', 'c', '');
INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (330, 2006, 'Medieval Indian History', 'Art Architecture and Literature', 'In Indian history, who was Abdul Hamid Lahori?', '{"a":"An important military commander during Akbar’s reign","b":"An official historian of the reign of Shah Jahan","c":"An important noble and confidant of Aurangzeb","d":"A chronicler and poet during the reign of Muhammad Shah"}', 'b', '');
INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (331, 2003, 'Medieval Indian History', 'Art Architecture and Literature', 'Consider the following statement: 1. Kitab I Nauras, a collection of songs in praise of Hindu deities and Muslim saints, was written by Ibrahim Adil Shah II 2. Amir Khusrau was the originator in India of the early form of the musical style known as Qawwali. Which of these statements is/are correct?', '{"a":"Only 1","b":"Only 2","c":"Both 1 and 2","d":"Neither 1 nor 2"}', 'c', '');
