INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (589, 1999, 'Modern Indian History', 'Last Phase 1940-1950', '“It made its proposals in May. It still wanted a united India. There was to be a Federal Union composed of British provinces.” The above quotation is related to:', '{"a":"Simon Commission","b":"Gandhi­Irwin Pact","c":"Cripps Mission","d":"Cabinet Mission"}', 'd', '');
