INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (591, 1999, 'Modern Indian History', 'Last Phase 1940-1950', 'Which one of the following leaders of the Congress was totally in favour of the Cabinet Mission Plan?', '{"a":"Mahatma Gandhi","b":"Jawaharlal Nehru","c":"Sardar Patel","d":"Maulana Abul Kalam Azad"}', 'c', '');
