INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (595, 1998, 'Modern Indian History', 'Last Phase 1940-1950', 'When the Indian Muslim League was inducted into the interim government in 1946, Liyaqat Ali Khan was assigned the portfolio of:', '{"a":"Foreign affairs","b":"Home","c":"Finance","d":"Defence"}', 'c', '');
