INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (597, 1998, 'Modern Indian History', 'Last Phase 1940-1950', 'At the time of India’s Independence, Mahatma Gandhi was:', '{"a":"A member of Congress Working Committee","b":"Not a member of the Congress","c":"The President of the Congress","d":"The General Secretary of the Congress"}', 'b', '');
INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (598, 1998, 'Modern Indian History', 'Last Phase 1940-1950', 'What is the correct sequence of the following events? I. The August Offer II. The I.N.A. trial III. The Quit India Movement IV. The Royal Indian Naval Ratings’ Revolt Select the correct answer using the codes given below: Codes:', '{"a":"I, III, II, IV","b":"III, I, II, IV","c":"I, III, IV, II","d":"III, I, IV, II"}', 'a', '');
INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (599, 1996, 'Modern Indian History', 'Last Phase 1940-1950', 'Consider the following statements about Jawaharlal Nehru: I. He was the President of the Congress Party in 1947. II. He presided over the Constituent Assembly. III. He formed the first Congress Ministry in United Province before India’s independence. Of these statements:', '{"a":"I, II and III are correct","b":"I and III are correct","c":"I and II are correct","d":"None is correct"}', 'd', '');
