INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (601, 1996, 'Modern Indian History', 'Last Phase 1940-1950', 'Who among the following suggested the winding up of the Indian National Congress after India attained independence?', '{"a":"C. Rajagopalachari","b":"Acharya Kripalani","c":"Mahatma Gandhi","d":"Jayaprakash Narain"}', 'c', '');
INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (602, 1996, 'Modern Indian History', 'Last Phase 1940-1950', 'Which one of the following first mooted the idea of a constituent assembly to frame a constitution for India?', '{"a":"Swaraj Party in 1934","b":"Congress Party in 1936","c":"Muslim League in 1942","d":"All Parties Conference in 1946"}', 'a', '');
