INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (630, 2006, 'Modern Indian History', 'Literature', 'Which one of the following revolts was made famous by Bankim Chandra Chatterjee in his novel Anand Math?', '{"a":"Bhil uprising","b":"Rangpur and Dinapur uprising","c":"Bishnupur and Birbhum rebellion","d":"Sanyasi rebellion"}', 'd', '');
