INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (633, 1999, 'Modern Indian History', 'Literature', 'Which one of the following statements is not correct?', '{"a":"‘Neel Darpan’ was a play based on the exploitation of the indigo farmers","b":"The author of the play ‘Ghashiram Kotwal’ is Vijay Tendulkar","c":"The play ‘Navanna’ by Nabin Chandra Das was based on the famine of Bengal","d":"Urdu theatre used to depend heavily on Parsi theatre"}', 'c', '');
