INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (640, 2011, 'Modern Indian History', 'Revolutionaries', 'With reference to the Indian freedom struggle, Usha Mehta is well-known for?', '{"a":"Running the secret congress radio in the wake of the quit India movement.","b":"Participating in the second round table conference.","c":"Leading a contingent of Indian national army.","d":"Assisting in the formation of Interim government under Pandit Jawaharlal Nehru."}', 'a', '');
INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (641, 2006, 'Modern Indian History', 'Revolutionaries', 'Consider the following statements about Madam Bhikaji Cama: 1. Madam Cama unfurled the National Flag at the international Socialist Conference in Paris in 1907. 2. Madam Cama served as private secretary to Dadabhai Naoroji. 3. Madam Cama was born to Parsi parents. Which of the statements given above is/are correct?', '{"a":"1, 2 and 3","b":"2 and 3, only","c":"1 and 2, only","d":"3 only"}', 'b', '');
