INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (646, 1998, 'Modern Indian History', 'Revolutionaries', 'Who was the leader of the Ghadar Party?', '{"a":"Bhagat Singh","b":"Lala Hardayal","c":"Bal Gangadhar Tilak","d":"V. D. Savarkar"}', 'b', '');
