INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (648, 1996, 'Modern Indian History', 'Revolutionaries', 'Match List I with List II and select the correct answer by using the codes given below the lists: List I List II I. Abhinav Bharat Society A) Sri Aurobindo Ghosh II. Anushilan Samiti B) Lala Hardayal III. Ghadar Party C) C. R. Das VI. Swaraj Party D) V. D. Savarkar Codes:', '{"a":"I ­ D, II ­ A, III ­ C, IV ­ B","b":"I ­ A, II ­ D, III ­ C, IV ­ B","c":"I ­ A, II ­ D, III ­ B, IV ­ C","d":"I ­ D, II ­ A, III ­ B, IV – C"}', 'd', '');
