INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (2543, 2008, 'Science and Technology', 'Astrophysics and Space', 'Which one of the following is a spacecraft?', '{"a":"China","b":"European Union","c":"Japan","d":"USA"}', 'b', '');
