INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (2728, 2008, 'Current Affairs and GK', 'Nuclear Weapons and Treaties', 'Consider the following statements: 1. The Nuclear Suppliers Group has 24 countries as the members. 2. India is a member of the Nuclear Suppliers Group. Which of the statements given above is/are correct?', '{"a":"1 Only","b":"2 Only","c":"Both 1 and 2","d":"Neither 1 nor 2"}', 'd', '');
