INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (2758, 2016, 'Current Affairs and GK', 'International Orgs and Treaties', 'Which of the following is/are the indicator/indicators used by IFPRI to compute the Global Hunger Index Report? 1. Undernourishment 2. Child stunting 3. Child mortality Select the correct answer using the code given below.', '{"a":"1 only","b":"2 and 3 only","c":"1, 2 and 3","d":"1 and 3 only"}', 'c', '');
INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (2759, 2016, 'Current Affairs and GK', 'International Orgs and Treaties', 'With reference to ‘Organization for the Prohibition of Chemical Weapons (OPCW)’, consider the following statements: 1. It is an organization of European Union in working relation with NATO and WHO. 2. It monitors chemical industry to prevent new weapons from emerging. 3. It provides assistance and protection to States (Parties) against chemical weapons threats. Which of the statements given above is/are correct?', '{"a":"1 only","b":"2 and 3 only","c":"1 and 3 only","d":"1, 2 and 3"}', 'b', '');
INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (2760, 2015, 'Current Affairs and GK', 'International Orgs and Treaties', 'Amnesty International is:', '{"a":"An agency of the United Nations to help refugees of civil wars","b":"A global Human Rights Movement","c":"A non-governmental voluntary organization to help very poor people","d":"An inter-governmental agency to cater to medical emergencies in war-ravaged regions"}', 'b', '');
