INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (2763, 2015, 'Current Affairs and GK', 'International Orgs and Treaties', 'With reference to ‘Indian Ocean Rim Association for Regional Cooperation (IOR-ARC)’, Consider the following statements: 1. It was established very recently in response to incidents of piracy and accidents of oil spills 2. It is an alliance meant for maritime security only Which of the following statements given above is/are correct?', '{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"}', 'd', '');
INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (2764, 2015, 'Current Affairs and GK', 'International Orgs and Treaties', 'Consider the following countries: 1. China 2. France 3. India 4. Israel 5. Pakistan Which among the above are Nuclear Weapons States as recognized by the Treaty on the Nonproliferation of Nuclear Weapons, commonly known as Nuclear Non-Proliferation Treaty (NPT)?', '{"a":"1 & 2 only","b":"1, 3, 4 & 5 only","c":"2, 4 & 5 only","d":"1, 2, 3, 4 & 5"}', 'a', '');
INSERT OR REPLACE INTO pyq_corpus (id, year, subject, topic, question_text, options, correct_option, explanation) VALUES (2765, 2015, 'Current Affairs and GK', 'International Orgs and Treaties', 'The ‘Fortaleza Declaration’ recently in the news, is related to the affairs of:', '{"a":"ASEAN","b":"BRICS","c":"OECD","d":"WTO"}', 'b', '');
